def format_autodoc_docstring(lines):
    res = []
    in_literal = False
    for line in lines:
        if line.strip().startswith('::') or line.strip().endswith('::'):
            in_literal = True
            res.append(line)
        elif in_literal and not line.strip():
            res.append(line)
        else:
            res.append(line)
    return res

