import unittest
from sphinx.directives import format_autodoc_docstring

class TestDirectives(unittest.TestCase):
    def test_docstring_format(self):
        lines = ["Summary line", "", "Example::", "", "    code()"]
        out = format_autodoc_docstring(lines)
        self.assertEqual(out, lines)

if __name__ == '__main__': unittest.main()
